import sys
import threading

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def find_primes_in_range(start, end, result, lock):
    local_primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            local_primes.append(num)
    with lock:
        result.extend(local_primes)

def main():
    lines = sys.stdin.read().strip().split()
    if not lines:
        print("Primes: []")
        return

    start = int(lines[0])
    end = int(lines[1])
    t = int(lines[2])

    if start > end or t <= 0:
        print("Primes: []")
        return

    total_numbers = end - start + 1
    part_size = max(1, total_numbers // t)

    threads = []
    result = []
    lock = threading.Lock()

    for i in range(t):
        part_start = start + i * part_size
        if part_start > end:
            break
        part_end = min(part_start + part_size - 1, end)
        thread = threading.Thread(target=find_primes_in_range, args=(part_start, part_end, result, lock))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    result.sort()
    print("Primes:", result)

if __name__ == "__main__":
    main()
